  var noteValues = {'C': 0, 'D': 2, 'E': 4, 'F': 5, 'G':7, 'A':9, 'B':11};
  var notes = <int>[];

  for (var i = 0; i < musicString.length; i++) {
    var ch = musicString[i];

    if (noteValues.containsKey(ch)) {
      int value = noteValues[ch]!;
      // Add the value to the list
      notes.add(value);

      // Check if next character is a sharp (#)
      if (i + 1 < musicString.length && musicString[i+1] == '#') {
        // Sharp increases by 1 semitone
        notes.add(value + 1);
        i += 1;
      } else if (i + 1 < musicString.length && musicString[i+1] == '-') {
        // Flat decreases by 1 semitone
        notes.add(value - 1);
        i += 1;
      }
    }
  }

  return notes;
}

