List<String> parseNestedList(String input) {
  final queue = Queue<String>();
  final stack = Stack<int>();
  final chars = input.split('');
  var currentString = '';
  var inBrackets = false;

  for (int i = 0; i < chars.length; i++) {
    var c = chars[i];

    if (c == '\\' && !inBrackets) {
      // Escaped character, skip the next one
      currentString += c;
      i++; // Skip the escaped character
    } else if (c == '[' && !inBrackets) {
      inBrackets = true;
      stack.add(i);
      currentString += c;
    } else if (c == ']' && inBrackets) {
      if (stack.isNotEmpty) {
        int startIdx = stack.removeLast() + 1;
        // Extract substring between [ and ]
        String nestedStr = input.substring(startIdx, i);
        queue.add(nestedStr);
        currentString += c;
        inBrackets = false;
      } else {
        // No matching opening bracket, consider as part of content
        currentString += c;
      }
    } else if (c == ',' && inBrackets) {
      // Comma inside brackets separates elements
      queue.add(currentString);
      currentString = '';
    } else {
      currentString += c;
    }
  }

  // Add any remaining characters after last closing bracket
  if (inBrackets) {
    queue.add(currentString);
  } else {
    queue.add(currentString);
  }

  return queue.toList(); // Convert queue to list
