List<List<int>> getRow(List<List<int>> lst, int x) {
  List<List<int>> coords = [];

  for (int i = 0; i < lst.length; i++) {
    for (int j = 0; j < lst[i].length; j++) {
      if (lst[i][j] == x) {
        coords.add([i, j]);
      }
    }
  }

  coords.sort((a, b) {
    if (a[0] != b[0]) {
      return a[0].compareTo(b[0]);
    } else {
      return b[1].compareTo(a[1]);
    }
  });

  return coords;
}

