int isBored(String s) {
  final List<String> words = ['i', 'a', 'o'];
  if (s.isEmpty || !s.contains(' ') && !words.any((w) => w == s)) return -1;

  int count = 0;
  for (var i = 0; i < s.length; ++i) {
    var c = s[i];
    if (c >= 'A' && c <= 'Z') continue;
    if (c != ' ') {
      while (i + 1 < s.length && s[i + 1] == ' ') {
        ++i;
      }
      count += 1;
    } else {
      break;
    }
  }

  if (count > 3) return count;

  String currentWord = '';
  bool inWord = false;
  for (var i = 0; i < s.length; ++i) {
    var c = s[i];
    if (c == ' ') {
      if (inWord) {
        if (words.contains(currentWord)) {
          count -= 1;
        }
        inWord = false;
        currentWord = '';
      }
    } else {
      if (!inWord) {
        inWord = true;
        currentWord = '';
      }
      currentWord += c;
    }
  }

  if (inWord) {
    if (words.contains(currentWord)) {
      count -= 1;
    }
  }

  return count;
}
