int isBored(String s) {
  final Set<String> boringWords = {'i', 'a', 'o'};
  if (s.isEmpty || !s.contains(' ') && !boringWords.contains(s)) return -1;

  int wordCount = 0;
  for (int i = 0; i < s.length;) {
    final char = s[i];
    if (char.toUpperCase() == char.toLowerCase()) { // Check if it's a space or punctuation
      if (char == ' ') {
        if (wordCount > 3) return wordCount;
        // Skip spaces and check next character
        i++;
        continue;
      }
      // If not a space, skip this character as it's non-alphabetic
      i++;
    } else {
      // Start of a new word
      var word = '';
      while (i < s.length && s[i].toUpperCase() == s[i].toLowerCase()) {
        word += s[i++];
      }
      if (boringWords.contains(word)) {
        wordCount--;
      } else {
        wordCount++;
      }
    }
  }

  return wordCount;
}
