  if (arr.isEmpty || k <= 0) return [];

  final n = arr.length;
  if (k > n) return [arr.reduce(max)];

  final queue = List<int>.generate(n, (i) => i);
  var front = 0;
  var back = n - 1;

  while (front < back) {
    // Find the index of the next greater element
    var maxIndex = front;
    for (var j = front; j <= back; ++j) {
      if (arr[j] > arr[maxIndex]) {
        maxIndex = j;
      }
    }

    // Move elements to the right of the current max index to the left
    for (var j = maxIndex + 1; j <= back; ++j) {
      queue[front++] = queue[j];
    }

    // If we have found exactly k elements, break early
    if (front >= k) break;

    // Update the back pointer
    back--;
  }

  return queue.sublist(0, k).map((x) => arr[x]).toList();
}

