  final cols = grid[0].length;

  final dp = List.generate(rows * cols + 1, (_) => -1);
  final dirs = <int>[0, 1, 2, 3];
  final dx = [0, 1, 0, -1]; // down, right
  final dy = [1, 0, -1, 0]; // right, down

  void dfs(int x, int y, int steps) {
    if (x < 0 || y < 0 || x >= rows || y >= cols) return;

    var idx = x * cols + y;
    if (dp[idx] != -1 && dp[idx] <= steps) return;
    dp[idx] = steps; 

    for (var i in dirs) {
      dfs(x + dx[i], y + dy[i], steps + grid[x][y]);
    }
  }

  dfs(0, 0, 0); 
  return dp.toList();
