String solve(String s) {
  int n = s.length;
  if (n == 0) return "";

  // Find the length of the longest palindromic substring
  int maxLen = 1, start = 0;
  for (int i = 0; i < n - 1; i++) {
    // Odd length palindrome
    int l = i, r = i;
    while (l >= 0 && r < n && s[l] == s[r]) {
      l--;
      r++;
    }
    int len = r - l - 1;
    if (len > maxLen) {
      maxLen = len;
      start = l + 1;
    }

    // Even length palindrome
    l = i;
    r = i + 1;
    while (l >= 0 && r < n && s[l] == s[r]) {
      l--;
      r++;
    }
    len = r - l - 1;
    if (len > maxLen) {
      maxLen = len;
      start = l + 1;
    }
  }

  return s.substring(start, start + maxLen);
}

